<script setup lang="ts">
import { ref } from 'vue'
import ProductState from '../../../frontend-shared/ProductState.vue'
import { requestValidatedData, ApiError } from '../services/http'
import { useAuth, leaveManagement } from '../composables/useAuth'
import { isManagedUser, isRoleChange, type ManagedUser as User } from '../services/management'
const id=ref(''),user=ref<User|null>(null),busy=ref(false),message=ref(''),auth=useAuth(),queryState=ref<'empty'|'loading'|'denied'|'unavailable'>('empty')
function roleLabel(role: User['role']): string { return role === 'super_admin' ? '超级管理员' : '普通用户' }
async function lookup(){if(busy.value)return;user.value=null;message.value='';queryState.value='empty';if(!/^[1-9][0-9]*$/.test(id.value)){message.value='请输入精确正整数用户 ID。';return}busy.value=true;queryState.value='loading';try{user.value=await requestValidatedData('/admin/users/'+id.value,isManagedUser)}catch(e){queryState.value=e instanceof ApiError&&e.status===403?'denied':'unavailable';message.value=e instanceof ApiError&&e.status===403?'当前账号无权查询用户，请联系其他管理员。':'用户不存在或查询失败，请检查 ID 后重试。'}finally{busy.value=false}}
async function change(){const target=user.value;if(!target||busy.value)return;const role=target.role==='user'?'super_admin':'user';if(!window.confirm(`确认将用户 ${target.id} 的角色变更为 ${role}？`))return;busy.value=true;message.value='';try{const result=await requestValidatedData('/admin/users/'+target.id+'/role',isRoleChange,{method:'PUT',body:JSON.stringify({role})});if(target.id===auth.user.value?.id&&role==='user'){user.value=null;await leaveManagement();return}user.value=result.user;message.value=result.changed?'角色已变更':'角色未改变'}catch(e){message.value=e instanceof ApiError&&e.status===409?'引导超级管理员不可降级':'角色变更失败'}finally{busy.value=false}}
</script>
<template><section><h2>用户角色</h2><form class="filter-grid" @submit.prevent="lookup"><label>精确用户 ID <input v-model="id" inputmode="numeric" autocomplete="off" /></label><button class="button" type="submit" :disabled="busy">查询用户</button></form><ProductState v-if="busy && !user" state="loading" message="正在查询用户…" /><ProductState v-else-if="!user && message" :state="queryState" :message="message" action-label="重试" @retry="lookup" /><p v-else-if="message" class="notice" role="status">{{message}}</p><article class="panel" v-if="user"><p>ID：{{user.id}} · {{user.username}}</p><p>角色：{{roleLabel(user.role)}} <code class="technical-field">({{user.role}})</code></p><p>{{new Date(user.created_at).toLocaleString()}} · {{Intl.DateTimeFormat().resolvedOptions().timeZone}}</p><p>引导账号：{{user.is_bootstrap_super_admin?'是':'否'}}</p><button class="button" type="button" :disabled="busy||user.is_bootstrap_super_admin" @click="change">{{user.role==='user'?'提升为超级管理员':'降级为普通用户'}}</button></article></section></template>
